"""Write every CPT in the model to docs/cpt_tables.md (full tables for the report)."""
import os
import sys
from itertools import product

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from src.model import STATES, build_model


def main():
    model = build_model()
    lines = ["# Full CPT Tables", "",
             "Generated by `scripts/print_cpts.py`. See `cpts.md` for the reasoning behind each table.", ""]

    for var in STATES:
        cpd = model.get_cpds(var)
        parents = cpd.variables[1:]
        title = f"Pr({var} | {', '.join(parents)})" if parents else f"Pr({var})"
        lines += [f"## {title}", ""]
        lines.append("| " + " | ".join(list(parents) + STATES[var]) + " |")
        lines.append("|" + "---|" * (len(parents) + len(STATES[var])))
        if not parents:
            lines.append("| " + " | ".join(f"{v:.2f}" for v in cpd.values) + " |")
        else:
            for combo in product(*[STATES[p] for p in parents]):
                idx = tuple(STATES[p].index(v) for p, v in zip(parents, combo))
                probs = [cpd.values[(i,) + idx] for i in range(len(STATES[var]))]
                lines.append("| " + " | ".join(list(combo) + [f"{p:.2f}" for p in probs]) + " |")
        lines.append("")

    out = os.path.join(ROOT, "docs", "cpt_tables.md")
    with open(out, "w") as f:
        f.write("\n".join(lines))
    print("Saved", out)


if __name__ == "__main__":
    main()
